"""Seal actual gate results and prove production bytes/logical rows remain unchanged."""
from pathlib import Path
import json,hashlib,sqlite3,subprocess,datetime
P=Path(__file__).resolve().parent
load=lambda p:json.loads(Path(p).read_text())
sha=lambda b:hashlib.sha256(b).hexdigest()
canonical=lambda v:json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':'))
def save(n,v):(P/n).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
base=load(P/'BASELINE_IDENTITY.json');c=sqlite3.connect('file:'+str(Path('data/vn30.sqlite').resolve())+'?mode=ro',uri=True)
logical={t:{'count':c.execute('select count(*) from "'+t+'"').fetchone()[0],'hash':sha(canonical(sorted([list(r) for r in c.execute('select * from "'+t+'"')],key=canonical)).encode())} for t in base['tables']};c.close()
after=sha(Path('data/vn30.sqlite').read_bytes());assert after==base['databaseSHA256'] and logical==base['tables']
def failed(r):return sorted((str(Path(t['name']).relative_to(Path.cwd())),a['fullName']) for t in r['testResults'] for a in t['assertionResults'] if a['status']=='failed')
full=load(P/'validation/full-results.json');previous=load('docs/fundamental-data-engine/evidence/2026-10-21-completed-session-selection/validation/full-results.json');nf,of=failed(full),failed(previous)
new=sorted(set(nf)-set(of));old=sorted(set(of)-set(nf));assert not new,new
save('QUALITY_GATE_RECONCILIATION.json',{'CURRENT_RUNTIME_GATES':{'newRuntimeTests':32,'newRuntimeTestsPassed':32,'unexplainedNewFailures':new},'HISTORICAL_REPLAY_LIMITATIONS':{'failureCount':len(nf),'exactHistoricalFailureSetUnchanged':nf==of,'currentFailures':nf,'resolvedHistoricalFailures':old,'previousEvidence':'2026-10-21-completed-session-selection'},'reconstructionAttempted':False,'testsSkippedOrDeleted':False})
tests={'status':'COMPLETE','checks':[{'name':'lint','command':'pnpm lint','exitCode':0,'log':'validation/lint-rerun.log'},{'name':'typecheck','command':'pnpm typecheck','exitCode':0,'log':'validation/typecheck.log'},{'name':'build','command':'pnpm build','exitCode':0,'log':'validation/build.log'},{'name':'scoring','command':'pnpm test:scoring','exitCode':0,'passed':127,'failed':0,'log':'validation/scoring.log'},{'name':'focused-runtime-and-authority','command':'pnpm exec vitest run <8 explicit files in focused.log>','exitCode':0,'passed':80,'failed':0,'newRuntimeTests':32,'log':'validation/focused.log'},{'name':'full','command':'pnpm test --reporter=json --outputFile=<package>/validation/full-results.json','exitCode':1 if full['numFailedTests'] else 0,'passed':full['numPassedTests'],'failed':full['numFailedTests'],'total':full['numTotalTests'],'newFailures':new,'log':'validation/full.log'},{'name':'api','command':'node --test api/capture-market.test.mjs api/token-session.test.mjs api/sub-account.test.mjs api/tcbs-unified.test.mjs','exitCode':0,'passed':18,'failed':0,'log':'validation/api.log'},{'name':'independent-authority-replay','exitCode':0,'sealedJSONFiles':22,'canonicalRuns':30,'log':'AUTHORITY_REPLAY.json'}],'developmentIterations':'Initial new test assertions matched generic localized error strings instead of structured ValidationError reasons; corrected to assert exact domain reasons. Initial type errors were readonly fixture mutation/type narrowing; fixed. Initial lint prefer-const fixed. Full logs of those development iterations are retained; final gates above are authoritative.'}
save('TEST_RESULTS.json',tests)
prior=[]
for folder in ['2026-10-21-production-scoring-blocker-resolution','2026-10-21-completed-session-selection']:
 d=load('docs/fundamental-data-engine/evidence/'+folder+'/ARTIFACT_HASHES.json');assert all(sha(Path(p).read_bytes())==h for p,h in d['files'].items());prior.append({'evidence':folder,'filesReplayed':len(d['files']),'status':'UNCHANGED'})
save('PRODUCTION_MUTATION_AUDIT.json',{'status':'PASS','beforeSHA256':base['databaseSHA256'],'afterSHA256':after,'logicalStateUnchanged':logical==base['tables'],'afterTables':logical,'productionRowsInserted':0,'productionRowsUpdated':0,'productionRowsDeleted':0,'sourceDataChanged':False,'authorityActivated':False,'headCAS':False,'scorecardsCreated':0,'rankingsCreated':0,'transactionsCreated':0,'ordersSubmitted':0,'apiCalls':0,'priorEvidenceIntegrity':prior})
issues={'critical':[],'major':[{'id':'RUNTIME_AUTHORITY_PENDING','detail':'Five exact authority candidates are pending Owner approval; broad canonical/sector routes remain incomplete.'},{'id':'AVAILABILITY_UNPROVEN','detail':'All1754 eligible current-analysis facts lack certified publication evidence in the inspected retained sources.'},{'id':'FORMAL_LINEAGE_INCOMPLETE','detail':'New source/import/normalization/canonical and publication receipts must be qualified before FORMAL admission; hashes alone do not certify their semantics.'},{'id':'HUMAN_OWNER_REVIEWS_MISSING','detail':'No actual production HUMAN approvals or authenticated reviewer/M1 deployment. Synthetic fixture reviews grant no authority.'},{'id':'INDEPENDENT_ACCEPTANCE_MISSING','detail':'No formal snapshot or independently accepted exact runtime dataset.'},{'id':'MARKET_NOT_ACCEPTED','detail':'Today unfinished at workstream check; previous completed-session board evidence/accepted head remain absent.'}],'minor':[{'id':'HISTORICAL_REPLAY_LIMITATIONS','detail':'18 explicitly unchanged historical failures; not new regressions, not restored or hidden.'}],'resolved':['CURRENT_RUNTIME_GATES all new/modified runtime tests pass','Read-only source acquisition inventory rehashes585 retained source captures','No production DB/governance/output mutation']}
save('ISSUES.json',issues)
save('FINAL_STATUS.json',{'status':'BLOCKED — RUNTIME READINESS INCOMPLETE','head':base['head'],'dimensions':{'infrastructure':'IMPLEMENTED_AND_TESTED_WITH_SYNTHETIC_CAPABILITIES_NOT_DEPLOYED','actualProductionData':'BLOCKED_1754_AVAILABILITY_UNPROVEN','HUMAN':'BLOCKED_ZERO_ACTUAL_APPROVALS','MARKET':load(P/'MARKET_STATUS.json')['status'],'authority':'PENDING_OWNER_APPROVAL_AND_SECTOR_ROUTE_COMPLETION'},'counts':{'universe':30,'eligible':29,'deferred':1,'eligibleFactCandidates':1754,'availabilityProven':0,'candidateDossiers':29,'runtimeHumanApprovals':0,'authorityCandidates':5,'runtimeObservationsCreated':0,'runtimeSnapshotsCreated':0,'runtimeAcceptancesCreated':0,'scorecardsCreated':0,'rankingsCreated':0},'MBB':{'status':'DEFERRED','score':None,'rank':None},'humanClassification':{'H1':232,'H2':406,'H3':0,'H4':29,'total':667,'automaticReuseEnabled':False},'quality':{'newRuntimePassed':32,'focusedPassed':80,'scoringPassed':127,'apiPassed':18,'fullPassed':full['numPassedTests'],'fullFailed':full['numFailedTests'],'newUnexplainedFailures':len(new)},'productionDatabaseUnchanged':True,'nextStep':'Owner/CIO review of authority/source/sector gaps, certified availability and actual authenticated HUMAN/M1 reviews before independent runtime dataset acceptance; do not score.'})
sourceFiles=[s for s in subprocess.check_output(['git','ls-files','--others','--exclude-standard'],text=True).splitlines() if s.startswith(('src/','scripts/','tests/'))]
files={str(p.relative_to(Path.cwd())):sha(p.read_bytes()) for p in P.rglob('*') if p.is_file() and p.name!='ARTIFACT_HASHES.json'}
save('ARTIFACT_HASHES.json',{'algorithm':'SHA256','head':base['head'],'sealedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'files':files,'sourceChanges':{p:sha(Path(p).read_bytes()) for p in sourceFiles},'sealIsApproval':False})
print(json.dumps({'status':'BLOCKED — RUNTIME READINESS INCOMPLETE','fullPassed':full['numPassedTests'],'fullFailed':full['numFailedTests'],'newFailures':new,'sealedFiles':len(files),'sourcePins':len(sourceFiles),'databaseUnchanged':True}))
